const fs = require('fs');
const zlib = require('zlib');
const path = require('path');

const docxPath = '/workspace/testbed/docs/travel_summary.docx';
const buf = fs.readFileSync(docxPath);

// ---- Step 1: Parse all zip entries ----
const entries = [];
let offset = 0;
while (offset < buf.length - 4) {
  if (buf[offset] === 0x50 && buf[offset+1] === 0x4b && buf[offset+2] === 0x03 && buf[offset+3] === 0x04) {
    const version = buf.readUInt16LE(offset + 4);
    const flags = buf.readUInt16LE(offset + 6);
    const compressionMethod = buf.readUInt16LE(offset + 8);
    const crc32 = buf.readUInt32LE(offset + 14);
    const compressedSize = buf.readUInt32LE(offset + 18);
    const uncompressedSize = buf.readUInt32LE(offset + 22);
    const fnameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const fname = buf.toString('utf8', offset + 30, offset + 30 + fnameLen);
    const dataStart = offset + 30 + fnameLen + extraLen;
    const headerStart = offset;

    let data;
    if (compressionMethod === 0) {
      data = buf.slice(dataStart, dataStart + compressedSize);
    } else {
      data = buf.slice(dataStart, dataStart + compressedSize);
    }

    entries.push({ fname, compressionMethod, compressedSize, uncompressedSize, dataStart, headerStart, fnameLen, extraLen, data, flags, crc32 });
    offset = dataStart + compressedSize;
  } else {
    offset++;
  }
}

// ---- Step 2: Modify word/document.xml ----
const docEntry = entries.find(e => e.fname === 'word/document.xml');
let xml;
if (docEntry.compressionMethod === 0) {
  xml = docEntry.data.toString('utf8');
} else {
  xml = zlib.inflateRawSync(docEntry.data).toString('utf8');
}

// The note to append
const note = \"Maya Chen's Seattle travel records include a confirmed flight, one cancelled hotel reservation, and three car rentals (two confirmed, one cancelled). Please refer to the details above for reference.\";

// Create a new paragraph XML to insert before </w:body>
const newParagraph = '<w:p><w:pPr><w:pStyle w:val=\"Normal\"/></w:pPr><w:r><w:t>' + note.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/'/g, '&apos;') + '</w:t></w:r></w:p>';

// Insert before </w:body>
xml = xml.replace('</w:body>', newParagraph + '</w:body>');

// ---- Step 3: Rebuild the zip file using the docx-pdf or manual approach ----
// We'll rebuild using a simple approach: re-create the zip with updated content

const { execSync } = require('child_process');

// Write modified XML to temp, then rebuild docx
const tmpDir = '/tmp/docx_rebuild';
fs.mkdirSync(tmpDir, { recursive: true });

// Extract all entries
for (const entry of entries) {
  let content;
  if (entry.compressionMethod === 0) {
    content = entry.data;
  } else {
    content = zlib.inflateRawSync(entry.data);
  }

  if (entry.fname === 'word/document.xml') {
    content = Buffer.from(xml, 'utf8');
  }

  const outPath = path.join(tmpDir, entry.fname);
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, content);
}

console.log('Files extracted and modified. Entries:', entries.map(e => e.fname));
