const fs = require('fs');
const zlib = require('zlib');
const PDFDocument = require('/workspace/node_modules/pdfkit');

// ---- Read docx content ----
const buf = fs.readFileSync('/workspace/testbed/docs/travel_summary.docx');
let offset = 0;
while (offset < buf.length - 4) {
  if (buf[offset]===0x50 && buf[offset+1]===0x4b && buf[offset+2]===0x03 && buf[offset+3]===0x04) {
    const cm = buf.readUInt16LE(offset+8);
    const cs = buf.readUInt32LE(offset+18);
    const fl = buf.readUInt16LE(offset+26);
    const el = buf.readUInt16LE(offset+28);
    const fn = buf.toString('utf8', offset+30, offset+30+fl);
    const ds = offset+30+fl+el;

    if (fn === 'word/document.xml') {
      const d = buf.slice(ds, ds+cs);
      const xml = cm===0 ? d.toString() : zlib.inflateRawSync(d).toString();

      // Extract paragraphs with style info
      const paragraphs = xml.split(/<\/w:p>/);
      const lines = [];
      for (const p of paragraphs) {
        const isHeading = /<w:pStyle\s+w:val=\"Heading/.test(p);
        const isBold = /<w:b[\s\/>]/.test(p) || isHeading;
        const t = [];
        const r = /<w:t[^>]*>([^<]*)<\/w:t>/g;
        let m;
        while ((m = r.exec(p)) !== null) t.push(m[1]);
        if (t.length) {
          let text = t.join('');
          // Decode XML entities
          text = text.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&apos;/g,\"'\").replace(/&quot;/g,'\"');
          lines.push({ text, isHeading, isBold });
        }
      }

      // ---- Create PDF ----
      const doc = new PDFDocument({ margin: 50, size: 'A4' });
      const output = fs.createWriteStream('/workspace/testbed/docs/travel_summary.pdf');
      doc.pipe(output);

      for (const line of lines) {
        if (line.isHeading) {
          doc.moveDown(0.5);
          doc.fontSize(16).font('Helvetica-Bold').text(line.text);
          doc.moveDown(0.3);
        } else {
          doc.fontSize(9).font('Helvetica').text(line.text);
        }
      }

      doc.end();
      output.on('finish', () => {
        console.log('PDF created successfully at /workspace/testbed/docs/travel_summary.pdf');
        console.log('Size:', fs.statSync('/workspace/testbed/docs/travel_summary.pdf').size, 'bytes');
      });
      break;
    }
    offset = ds+cs;
  } else offset++;
}
"

